from datetime import date, datetime, timezone
from typing import Any
import copy
import hashlib
import hmac
import json
import re

from trialops.governance import apply_reuse_action


_ID_PATTERN = re.compile(r"[A-Za-z0-9_-]+\Z")
_ISO_DATE_PATTERN = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")
_CONTROL_OR_INVISIBLE = re.compile(
    "[\u0000-\u001f\u007f-\u009f\u00ad\u061c"
    "\u180b-\u180e\u200b-\u200f\u2028\u2029\u202a-\u202e"
    "\u2060-\u2064\u2066-\u206f\ufeff\ufff9-\ufffb"
    "\ud800-\udfff]"
)

_SUBJECT_FIELDS = frozenset(
    {
        "id",
        "name",
        "birth_date",
        "email",
        "country",
        "visits",
        "consents",
        "purge_after",
    }
)
_CONSENT_FIELDS = frozenset({"purpose", "signed_on", "withdrawn_on"})


def _field(record: Mapping[str, Any], name: str) -> Any:
    try:
        return record[name]
    except (KeyError, TypeError):
        raise ValueError(f"missing required field {name}") from None


def _date(value: Any, field: str) -> date:
    if not isinstance(value, str) or _ISO_DATE_PATTERN.fullmatch(value) is None:
        raise ValueError(f"{field} must be an ISO date")
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError, OverflowError):
        raise ValueError(f"{field} must be an ISO date") from None


def _text(value: Any, field: str, *, nonempty: bool = False) -> str:
    if not isinstance(value, str) or (nonempty and not value):
        qualifier = "a non-empty" if nonempty else "a"
        raise ValueError(f"{field} must be {qualifier} string")
    if _CONTROL_OR_INVISIBLE.search(value) is not None:
        raise ValueError(f"{field} must not contain control or invisible characters")
    return value


def _allowed_fields(record: Mapping[str, Any], allowed: frozenset[str]) -> str | None:
    unexpected = sorted(str(key) for key in record.keys() if key not in allowed)
    if unexpected:
        return ", ".join(unexpected)
    return None


def _validate_purpose(purpose: Any) -> str:
    purpose = _text(purpose, "purpose", nonempty=True)
    if not purpose.strip():
        raise ValueError("purpose must not be blank")
    try:
        purpose.encode("utf-8")
    except UnicodeError:
        raise ValueError("purpose must contain valid Unicode") from None
    return purpose


def _validate_secret(secret: Any) -> str:
    if not isinstance(secret, str) or not secret:
        raise ValueError("secret must be a non-empty string")
    if _CONTROL_OR_INVISIBLE.search(secret) is not None:
        raise ValueError("secret must not contain control or invisible characters")
    try:
        secret.encode("utf-8")
    except UnicodeError:
        raise ValueError("secret must contain valid Unicode") from None
    return secret


def _validate_country(country: str) -> str:
