    consents = [_parse_consent(consent) for consent in consents_value]

    purge_after = _date(_field(subject, "purge_after"), "purge_after")

    return subject_id, visits, consents, country, birth_date.year, purge_after


def _active_consent(
    consents: list[tuple[str, date, date | None]], purpose: str, on: date
) -> bool:
    return any(
        consent_purpose == purpose
        and signed_on <= on
        and (withdrawn_on is None or withdrawn_on > on)
        for consent_purpose, signed_on, withdrawn_on in consents
    )


def export_subjects(
    subjects: Iterable[Mapping[str, Any]], *, purpose: str, secret: str, on: date
) -> dict[str, Any]:
    """Export only active, unpurged records without direct identifiers."""

    purpose = _validate_purpose(purpose)
    secret = _validate_secret(secret)
    if not isinstance(on, date) or isinstance(on, datetime):
        raise ValueError("on must be a date")
    if isinstance(subjects, (str, bytes, Mapping)) or not isinstance(
        subjects, Iterable
    ):
        raise ValueError("subjects must be an iterable of records")

    rows: list[dict[str, Any]] = []
    seen_ids: set[str] = set()

    for subject in subjects:
        if not isinstance(subject, Mapping):
            raise ValueError("each subject must be a mapping")
        unexpected = _allowed_fields(subject, _SUBJECT_FIELDS)
        if unexpected:
            raise ValueError(f"subject contains unsupported fields: {unexpected}")

        subject_id, visits, consents, country, birth_year, purge_after = _parse_subject(
            subject
        )
        if subject_id in seen_ids:
            raise ValueError("DUPLICATE_SUBJECT_ID")
        seen_ids.add(subject_id)

        if not _active_consent(consents, purpose, on) or purge_after < on:
            continue

        message = f"{purpose}:{subject_id}".encode("utf-8")
        pseudonym = hmac.new(
            secret.encode("utf-8"), message, hashlib.sha256
        ).hexdigest()[:16]
        rows.append(
            {
                "pseudonym": pseudonym,
                "country": country,
                "birth_year": birth_year,
                "visits": [value.isoformat() for value in visits],
            }
        )

    rows.sort(key=lambda row: row["pseudonym"])
    try:
        canonical_rows = json.dumps(
            rows,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError, UnicodeError):
        raise ValueError("export rows must contain valid JSON text") from None

    return {
        "rows": rows,
        "manifest": {
            "algorithm": "sha256",
            "count": len(rows),
            "sha256": hashlib.sha256(canonical_rows).hexdigest(),
        },
    }


def _utc_now(now: Any) -> datetime:
    if not isinstance(now, datetime):
        raise ValueError("INVALID_NOW")
    try:
        if now.tzinfo is None or now.utcoffset() is None:
            raise ValueError("INVALID_NOW")
        return now.astimezone(timezone.utc)
    except (OverflowError, ValueError) as exc:
        raise ValueError("INVALID_NOW") from exc


def execute_reuse_export(
    request: dict[str, object],
    subjects: Iterable[Mapping[str, Any]],
    *,
    actor: str,
    secret: str,
    now: datetime,
) -> dict[str, object]:
    """Run one governed, pseudonymized export of the approved reuse request.

    Governance is the single gate: the subject records are only read once the
    approved snapshot has passed every governance check, so rejected, expired,
    or already executed requests never consume them.  Export failures surface
    as the governance ``EXECUTION_FAILED`` error and leave the approved request
    and its history untouched.
    """

    if not isinstance(request, dict):
        raise TypeError("request must be a dict")
    now_utc = _utc_now(now)
    on = now_utc.date()

    def _execute(approved: dict[str, object]) -> dict[str, Any]:
        purpose = approved.get("purpose")
        if not isinstance(purpose, str) or not purpose.strip():
            raise ValueError("approved request must state a non-empty purpose")
        try:
            # Snapshot the caller's records so the export cannot observe or
            # mutate them, and so a repeated execution never re-reads them.
            snapshot = copy.deepcopy(list(subjects))
        except Exception:
            raise ValueError("INVALID_SUBJECTS") from None
        return export_subjects(snapshot, purpose=purpose, secret=secret, on=on)

    return apply_reuse_action(request, "execute", actor, now, executor=_execute)
